CREATE TABLE IF NOT EXISTS institutions (
    id           VARCHAR(100) PRIMARY KEY,
    name         TEXT         NOT NULL,
    city         TEXT,
    category     VARCHAR(50),
    specialties  TEXT,
    description  TEXT,
    phone        VARCHAR(50),
    email        VARCHAR(200),
    website      TEXT,
    source_url   TEXT,
    source_label TEXT,
    address      TEXT,
    sgk_contract BOOLEAN,
    free_service BOOLEAN,
    age_range    VARCHAR(50),
    services     TEXT,
    notes        TEXT
);

