-- STK, Vakıf & Dernekler
('tohum','Tohum Otizm Vakfı','İstanbul','ngo','Otizm Eğitimi|||Aile Desteği|||Farkındalık','Türkiye''nin en köklü otizm vakfı. Okul öncesi ve okul çağı çocuklar için erken müdahale programları, aile destek grupları, öğretmen eğitimleri ve ulusal farkındalık kampanyaları yürütür.','0212 257 75 00',NULL,'https://www.tohumotizm.org.tr',NULL,NULL,'Etiler, Beşiktaş, İstanbul',NULL,NULL,NULL,'Erken Müdahale|||Aile Destek Grubu|||Öğretmen Eğitimi|||Farkındalık Kampanyaları',NULL),
('otizmder','Otizm Derneği (OTİZM-DER)','Ankara','ngo','Hukuki Destek|||Savunuculuk|||Haklar','Otizm tanılı bireylerin ve ailelerinin haklarını savunur. Hukuki rehberlik, eğitim hakkı danışmanlığı ve BEP süreci desteği sunar.','0312 430 12 78','info@otizmder.org.tr','https://www.otizmder.org.tr',NULL,NULL,NULL,NULL,NULL,NULL,'Hukuki Danışmanlık|||Hak Savunuculuğu|||BEP Desteği|||Aile Destek Grubu',NULL),
('acev','AÇEV — Aile ve Çocuk Eğitimi Vakfı','İstanbul','ngo','Aile Eğitimi|||Erken Çocukluk|||Gelişim','Aile eğitimi ve erken çocukluk gelişimi alanında Türkiye''nin önde gelen sivil toplum kuruluşu. Anne-baba eğitim programları ve ev ziyareti hizmetleri sunar.','0212 281 11 54',NULL,'https://www.acev.org',NULL,NULL,'Levent, İstanbul',NULL,NULL,NULL,'Anne-Baba Okulu|||Ev Ziyareti Programları|||Erken Müdahale Eğitimi',NULL),
('otizm-vakfi','Türkiye Otizm Vakfı','İstanbul','ngo','Araştırma|||Farkındalık|||Aile Desteği','Otizm spektrum bozukluğu alanında araştırma, eğitim ve farkındalık projeleri yürüten vakıf. Aile destek programları ve bilgilendirme seminerleri düzenler.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Farkındalık Eğitimleri|||Araştırma Desteği|||Aile Seminerleri',NULL),
('engelsiz-yasam','Engelsiz Yaşam Derneği','Ankara','ngo','Bağımsız Yaşam|||İstihdam|||Haklar','Engelli bireylerin bağımsız yaşam becerilerini kazanmaları ve istihdam edilmeleri için çalışır. Hukuki danışmanlık ve toplumsal farkındalık faaliyetleri yürütür.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Bağımsız Yaşam Eğitimi|||İş Bulma Desteği|||Oryantasyon|||Hukuki Danışmanlık',NULL),
('ogbd','Otizm ve Gelişimsel Bozukluklar Derneği (OGBD)','İstanbul','ngo','Otizm|||Eğitim|||Aile Desteği','Otizm ve gelişimsel bozukluklar alanında aileleri bilgilendirmek, farkındalık oluşturmak ve destek grupları oluşturmak amacıyla kurulmuş dernek.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Aile Bilgilendirme|||Destek Grupları|||Seminerler',NULL),
('cocuk-gelisim-der','Türkiye Çocuk Gelişimi Derneği','Ankara','ngo','Çocuk Gelişimi|||Erken Müdahale|||Eğitim','Çocuk gelişimi uzmanlarını bir araya getiren mesleki dernek. Erken müdahale ve özel eğitim alanında rehberlik ve kaynak sağlar.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Mesleki Rehberlik|||Kaynak Kütüphanesi|||Uzman Yönlendirme',NULL),
('ozak','Türkiye Özürlüler Araştırma Vakfı (ÖZAK)','Ankara','ngo','Araştırma|||Haklar|||Politika','Engelli bireylerin haklarına yönelik araştırma ve savunuculuk faaliyetleri yürüten vakıf. Politika önerileri ve raporlar hazırlar.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Araştırma|||Savunuculuk|||Politika Geliştirme',NULL),
('engelli-hak-fed','Türkiye Engelli Hakları Federasyonu','Ankara','ngo','Hak Savunuculuğu|||Politika|||Hukuki Destek','Engelli bireylerin haklarını savunan çatı federasyonu. Yasal düzenlemelerin takibi ve hak ihlali bildirimi konularında destek verir.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Hak Savunuculuğu|||Hukuki Danışmanlık|||İtiraz Desteği',NULL),
('erg','Eğitim Reformu Girişimi (ERG)','İstanbul','ngo','Eğitim Politikası|||Kaynaştırma|||Araştırma','Türkiye''de eğitim politikasını araştıran ve kapsayıcı eğitim için savunuculuk yapan sivil toplum kuruluşu. Kaynaştırma eğitimi alanında önemli raporlar yayımlar.',NULL,NULL,'https://www.egitimreformugirisimi.org',NULL,NULL,NULL,NULL,NULL,NULL,'Araştırma Raporları|||Politika Önerileri|||Kapsayıcı Eğitim Savunuculuğu',NULL),

